"""Harness permission modes, per-connection limits and the review paths they gate."""
import contextlib,http.server,json,pathlib,subprocess,tempfile,threading,urllib.parse
PROJECT=pathlib.Path(__file__).resolve().parents[1];passed=[]
def check(name,value):assert value,name;passed.append(name)
class Page(http.server.BaseHTTPRequestHandler):
 def do_GET(self):
  query=urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query).get('q',[''])[0]
  body=json.dumps(dict(query=query,number_of_results=1,results=[dict(url='https://example.test/permission-modes',title='Permission modes',content='Harness permission modes gate the review dialog.',engine='probe')])).encode()
  self.send_response(200);self.send_header('Content-Type','application/json');self.send_header('Content-Length',str(len(body)));self.end_headers();self.wfile.write(body)
 def log_message(self,*a):pass
with tempfile.TemporaryDirectory(prefix='permission-modes-',dir=PROJECT/'output')as tmp,contextlib.ExitStack()as stack:
 base=pathlib.Path(tmp);workspace=base/'workspace';workspace.mkdir();(workspace/'keep.txt').write_text('Original saved work\n')
 server=http.server.HTTPServer(('127.0.0.1',0),Page);threading.Thread(target=server.serve_forever,daemon=True).start()
 stack.callback(server.shutdown);stack.callback(server.server_close)
 search_url='http://127.0.0.1:%d/search?q={query}'%server.server_address[1]
 p=stack.enter_context(subprocess.Popen([str(PROJECT/'output/headless/RLLM'),'--jsonl'],stdin=subprocess.PIPE,stdout=subprocess.PIPE,text=True))
 def op(value):
  p.stdin.write(json.dumps(value)+'\n');p.stdin.flush();r=json.loads(p.stdout.readline());assert 'value'in r,r;return r['value']
 def event(st,action,inputs=None):return op(dict(op='event',root=str(workspace),state=st,action=action,inputs=inputs or{}))
 def buttons(d):return(d['ui'].get('modal')or{}).get('buttons',d['ui'].get('rows')or[])
 def events(d):return[b['event']for b in buttons(d)]
 def fields(d):return{f['key']:f for f in(d['ui'].get('modal')or{}).get('fields',[])}
 def notice(d):return(d['state']or{}).get('notice','')
 def web(st,extra=None):
  settings=dict(search_url=search_url);settings.update(extra or{})
  st=dict(st);st['web']=settings;return st
 def searched(st,query):
  opened=event(st,'web_search')
  return opened,event(opened['state'],'web_search_review',dict(query=query))
 d=event(None,'resume')
 check('the chat surface carries the default harness permission mode',d['ui']['permission_mode']=='review'and d['ui']['permission_label']=='Ask')
 check('app settings exposes the permissions screen','permissions'in events(event(d['state'],'config')))
 menu=event(d['state'],'permission_modes')
 check('the permission menu offers exactly the three modes',events(menu)==['permission_mode:review','permission_mode:limited','permission_mode:yolo']and menu['state']['dialog']=='permission_modes')
 check('the conversation menu names the current mode','Permission mode · Ask'in[b['label']for b in buttons(event(d['state'],'chat_actions'))])
 d=event(d['state'],'profile_new');d=event(d['state'],'profile_save',dict(name='Probe',endpoint='http://127.0.0.1:9311/v1',model='probe-model',protocol='chat'))
 check('a connection is selected before permissions are configured',d['state']['profiles'][0]['name']=='Probe')
 d=event(d['state'],'permissions')
 check('permissions carries one dropdown per limit class for each connection',list(fields(d))==['mode','mode_0','web_0','file_0']and all(f['kind']=='choice'for f in fields(d).values()))
 check('every limit dropdown offers the inherit arm',all('inherit'in{o['value']for o in fields(d)[k]['options']}for k in['web_0','file_0']))
 check('the mode menu states that web search runs without a review','never reviewed'in fields(menu)['description']['value'])
 d=event(d['state'],'close')
 opened,ran=searched(web(d['state']),'permission modes')
 check('Ask mode runs a web search with no review dialog',ran['effect']is not None and ran['effect'].get('host')=='127.0.0.1'and ran['effect'].get('purpose')=='web_tool'and ran['state'].get('web_expected')is not None and ran['state'].get('pending')is None and ran['ui'].get('modal')is None)
 d=event(ran['state'],'cancel')
 opened,held=searched(web(d['state'],dict(search_without_review=False)),'reviewed search')
 check('the app-wide search review setting still asks',held['effect']is None and held['state'].get('pending',{}).get('tool')=='web_search')
 d=event(held['state'],'reject')
 def reviewed(label):
  opened=event(d['state'],'reader');opened=event(opened['state'],'manual_tool',dict(path='keep.txt'))
  check(label,opened['effect']is None and opened['state']['dialog']=='approval'and opened['state']['pending']['tool']=='read')
  return event(opened['state'],'reject')
 d=reviewed('the default mode reviews a manual workspace read')
 check('rejecting a reviewed read executes nothing',d['effect']is None and d['state'].get('pending')is None)
 d=event(d['state'],'permissions_save',dict(mode='yolo',mode_0='yolo'));check('saving permissions reports and applies the harness mode',d['state']['permission_mode']=='yolo'and d['ui']['permission_label']=='YOLO'and 'YOLO'in notice(d))
 opened=event(d['state'],'reader');opened=event(opened['state'],'manual_tool',dict(path='keep.txt'))
 check('YOLO dispatches the same read with no review dialog',opened['effect']is not None and opened['effect']['kind']=='tool'and opened['effect']['tool']=='read'and opened['state'].get('pending')is None and opened['ui'].get('modal')is None)
 d=event(opened['state'],'cancel')
 d=event(d['state'],'permissions_save',dict(mode='yolo',mode_0='review'))
 opened=event(d['state'],'reader');opened=event(opened['state'],'manual_tool',dict(path='keep.txt'))
 check('a tighter per-connection mode restores review while the harness stays YOLO',opened['state']['dialog']=='approval'and opened['state']['pending']['tool']=='read'and opened['state']['permission_mode']=='yolo')
 blocked=event(opened['state'],'permissions_save',dict(mode='yolo',mode_0='yolo'))
 check('permissions cannot be saved over an open review','Finish or cancel the current task or tool review first'in notice(blocked)and blocked['state']['notice_error'])
 d=event(blocked['state'],'reject')
 refused=event(d['state'],'permissions_save',dict(mode='reckless'))
 check('an unsupported permission mode is refused','Choose a supported permission mode'in notice(refused)and refused['state']['notice_error'])
 d=event(refused['state'],'permissions_save',dict(mode='limited',mode_0='review',file_0='off'))
 check('the file limit is stored per connection',d['state']['permissions']=={'0':{'mode':'review','file':'off'}})
 opened=event(d['state'],'reader');opened=event(opened['state'],'manual_tool',dict(path='keep.txt'))
 check('the file-off connection stages its read like any other review',opened['effect']is None and opened['state']['pending']['tool']=='read')
 approved=event(opened['state'],'approve')
 check('file access off refuses dispatch and names the connection',approved['effect']is None and approved['state']['notice_error']and'File access is off for Probe (App settings → Permissions)'in notice(approved))
 d=event(approved['state'],'reject')
 d=event(d['state'],'permissions_save',dict(mode='limited',mode_0='yolo',web_0='off'))
 opened,held=searched(web(d['state']),'blocked search')
 check('web access off blocks that connection search before execution',held['effect']is None and held['state']['notice_error']and'Web access is off for Probe (App settings → Permissions)'in notice(held)and held['state'].get('pending')is None)
 d=event(held['state'],'permissions_save',dict(mode='limited',mode_0='yolo'))
 opened,ran=searched(web(d['state']),'allowed search')
 check('the same connection searches without review once web access is back on',ran['effect']is not None and ran['effect'].get('host')=='127.0.0.1'and ran['state'].get('pending')is None)
 d=event(ran['state'],'cancel')
 d=event(d['state'],'permissions_save',dict(mode='limited',mode_0='limited'))
 opened=event(d['state'],'editor',dict(path='new.txt',content='Written under Limited\n'));opened=event(opened['state'],'editor_save',dict(path='new.txt',content='Written under Limited\n'))
 check('Limited reviews a write',opened['effect']is None and opened['state']['dialog']=='approval'and opened['state']['pending']['tool']=='write')
 d=event(opened['state'],'reject')
 switched=event(d['state'],'permissions_save',dict(mode='limited',mode_0='yolo'))
 wrote=event(switched['state'],'editor',dict(path='new.txt',content='Written by YOLO\n'));wrote=event(wrote['state'],'editor_save',dict(path='new.txt',content='Written by YOLO\n'))
 check('a YOLO connection writes without a review',wrote['effect']is not None and wrote['effect']['kind']=='tool'and wrote['effect']['tool']=='write'and wrote['state'].get('pending')is None)
 d=event(wrote['state'],'cancel')
 back=event(d['state'],'permissions_save',dict(mode='limited',mode_0='limited'))
 opened=event(back['state'],'reader');opened=event(opened['state'],'manual_tool',dict(path='keep.txt'))
 check('Limited runs a read-only operation without a dialog',opened['effect']is not None and opened['effect']['kind']=='tool'and opened['effect']['tool']=='read'and opened['state'].get('pending')is None)
 d=event(opened['state'],'cancel')
 d=event(d['state'],'permissions_save',dict(mode='review',mode_0='inherit'))
 check('clearing the per-connection limits leaves only the harness mode',d['state']['permissions']=={}and d['ui']['permission_mode']=='review')
 d=reviewed('cleared limits put an ordinary operation back on the review path')
record=dict(passed=len(passed),checks=passed,scope='Owner and manual operations through current public events against a real workspace and a local search endpoint: mode menu, per-connection dropdowns, never-reviewed web search, review paths, auto-dispatch and named refusals. Model-proposed operations reuse the same automatic_approval and harness_rules gates; physical Android rendering of the footer control remains separate.')
(PROJECT/'output/checks/permission_modes.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps(record,indent=2))
